import{_ as u,a0 as o,w as p,s as l,ao as r,I as s,x as e,a1 as a,A as i}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const U=JSON.parse('{"title":"每日Ubuntu小技巧 - 使用旧式Gnome风格的菜单 | LCTT x X-CMD","titleTemplate":false,"description":"每日Ubuntu小技巧 - 使用旧式Gnome风格的菜单 | LCTT (201312) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"每日Ubuntu小技巧 - 使用旧式Gnome风格的菜单 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"每日Ubuntu小技巧 - 使用旧式Gnome风格的菜单 | LCTT (201312) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201312/Daily Ubuntu Tips–Like GNOME Classic Menu？ Get Classic Menu Indicator","title":"每日Ubuntu小技巧 - 使用旧式Gnome风格的菜单","tag":"201312","desc":""},"relativePath":"201312/Daily Ubuntu Tips–Like GNOME Classic Menu？ Get Classic Menu Indicator.md","filePath":"[post].md"}'),d={name:"201312/Daily Ubuntu Tips–Like GNOME Classic Menu？ Get Classic Menu Indicator.md"};function m(b,t,c,C,T,M){const n=o("Link");return p(),l("div",null,[t[11]||(t[11]=r(`<h1 id="每日ubuntu小技巧-使用旧式gnome风格的菜单" tabindex="-1">每日Ubuntu小技巧 - 使用旧式Gnome风格的菜单 <a class="header-anchor" href="#每日ubuntu小技巧-使用旧式gnome风格的菜单" aria-label="Permalink to “每日Ubuntu小技巧 - 使用旧式Gnome风格的菜单”">​</a></h1><p>喜欢GNOME风格菜单？安装Class Menu Indicator吧。</p><p>对于那些从开始就一直关注Ubuntu操作系统的人，他们看见几乎所有的Ubuntu经历的改变。发生了许多的改变，尤其是在桌面部分。从经典的GNOME桌面环境到Unity，Ubuntu已经完全地重新设计了。</p><p>对于那些新用户，他们所知道的就是Unity桌面环境，仅仅只是听说过或者见过之前Ubuntu的原始GNOME桌面环境。</p><p>如果你是一个老资格用户，想要在Ubuntu的Unity回到GNOME风格的菜单，安装Classic Menu Indicator 可以解决这个问题。这个有趣的包被安装在顶部面板的通知区域，在Ubuntu中带回了GNOME风格菜单体验。</p><p>像经典的GNOME菜单一样，它包括所有的应用和经典菜单结构。对于曾经使用过它的人们是容易导航和开启应用。对于新用户，它也是容易掌握。</p><p>接下来的简短指导将会告诉你如何在Ubuntu中安装这个包。</p><p>马上开始，在键盘上按下 <strong>Ctrl – Alt – T</strong> 打开终端。</p><p>打开完毕后，运行下列命令，加入它的PPA文件</p><pre><code>sudo apt-add-repository ppa:diesch/testing
</code></pre><p>接来下，运行下列命令安装它。</p><pre><code>sudo apt-get update &amp;&amp; sudo apt-get install classicmenu-indicator
</code></pre><p>安装完成后，在Unity Dash中启动。它叫Classic Menu Indicator。当你启动它的时候，它会自动的嵌入顶部面板，如下图。</p><p><img src="http://www.liberiangeek.net/wp-content/uploads/2013/11/classic-menu-indicator.png" alt=""></p><h2 id="就是这样-使用并享受吧" tabindex="-1">就是这样，使用并享受吧！ <a class="header-anchor" href="#就是这样-使用并享受吧" aria-label="Permalink to “就是这样，使用并享受吧！”">​</a></h2>`,15)),s("p",null,[t[1]||(t[1]=e("via: ",-1)),a(n,{href:"http://www.liberiangeek.net/2013/11/daily-ubuntu-tipslike-gnome-classic-menu-get-classic-menu-indicator/"},{default:i(()=>[...t[0]||(t[0]=[e("http://www.liberiangeek.net/2013/11/daily-ubuntu-tipslike-gnome-classic-menu-get-classic-menu-indicator/",-1)])]),_:1})]),s("p",null,[t[4]||(t[4]=e("译者：",-1)),a(n,{href:"http://blog.csdn.net/Vic___"},{default:i(()=>[...t[2]||(t[2]=[e("Vic___",-1)])]),_:1}),t[5]||(t[5]=e(" 校对：",-1)),a(n,{href:"https://github.com/wxy"},{default:i(()=>[...t[3]||(t[3]=[e("wxy",-1)])]),_:1})]),s("p",null,[t[8]||(t[8]=e("本文由 ",-1)),a(n,{href:"https://github.com/LCTT/TranslateProject"},{default:i(()=>[...t[6]||(t[6]=[e("LCTT",-1)])]),_:1}),t[9]||(t[9]=e(" 原创翻译，",-1)),a(n,{href:"http://linux.cn/"},{default:i(()=>[...t[7]||(t[7]=[e("Linux中国",-1)])]),_:1}),t[10]||(t[10]=e(" 荣誉推出",-1))])])}const f=u(d,[["render",m]]);export{U as __pageData,f as default};
